{
  "name": "USB 原始通信组件",
  "name_en": "USB Raw Communicator",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于封装 pyusb 连接对象，为实验系统提供与 USB 连接设备之间的原始字节读写、超时、终止符和输入缓冲区管理功能。它主要用于底层通信，不对应某一特定硬件仪器。",
  "description_en": "This is a non-physical software communication component that wraps a pyusb connection object. It provides raw byte read/write access, timeout handling, terminator configuration, and input buffer management for USB-connected devices in laboratory systems. It is a low-level communication helper rather than a specific hardware instrument.",
  "tag_hints": [
    "raw USB communication",
    "pyusb",
    "instrument I/O",
    "byte stream read/write",
    "communication timeout",
    "input buffer flushing"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置 USB 地址",
      "description_en": "get/set the USB address"
    },
    {
      "action_name": "auto-close",
      "description": "关闭 USB 连接",
      "description_en": "close the USB connection"
    },
    {
      "action_name": "auto-flush_input",
      "description": "清空输入缓冲区",
      "description_en": "flush the input buffer"
    },
    {
      "action_name": "auto-read_raw",
      "description": "读取 USB 连接中的原始字节数据",
      "description_en": "read raw bytes from the USB connection"
    },
    {
      "action_name": "auto-seek",
      "description": "设置流位置",
      "description_en": "set the stream position"
    },
    {
      "action_name": "auto-tell",
      "description": "获取当前流位置",
      "description_en": "get the current stream position"
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置通信终止字符",
      "description_en": "get/set the communication termination character"
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置通信超时时间",
      "description_en": "get/set the communication timeout"
    },
    {
      "action_name": "auto-write_raw",
      "description": "向 USB 连接写入原始字节数据",
      "description_en": "write raw bytes to the USB connection"
    }
  ]
}

